#pragma once
#include <TFT_eSPI.h>

// Screen text is Ukrainian, so it uses smooth (VLW) fonts with Cyrillic generated by
// tools/gen_vlw.py. FONT_BUILTIN unloads them so TFT_eSPI's numbered fonts work again
// (e.g. font 7 for big digits).
enum UiFont { FONT_BUILTIN, FONT_SMALL, FONT_LARGE };

void useFont(TFT_eSPI &tft, UiFont font);
// Bold font sized so "<city of region> HH:MM" fits on one line (tools/gen_city_fonts.py).
// region -1: clock-only font. Holds only that city's letters and the clock digits.
void useCityFont(TFT_eSPI &tft, int region);
